def reverse_book(book):
    """Return extension code -> list of names, in book order."""
    pass

exercise.solution:
def reverse_book(book):
    out = {}
    for name, code in book.items():
        out.setdefault(code, []).append(name)
    return out

exercise.starter:
def read_setting(config, path, fallback):
    """Return the value at path, or fallback if unwalkable."""
    pass

exercise.solution:
def read_setting(config, path, fallback):
    if not path:                 # nothing to fetch
        return fallback
    cur = config
    for key in path:
        if not isinstance(cur, dict) or key not in cur:
            return fallback       # unwalkable step
        cur = cur[key]
    return cur                    # may be None — and that is correct

exercise.starter:
def top_extensions(log, k):
    """Return the k busiest codes; ties by numeric code."""
    pass

exercise.solution:
def top_extensions(log, k):
    counts = {}
    for code in log:
        counts[code] = counts.get(code, 0) + 1
    ranked = sorted(counts, key=lambda c: (-counts[c], int(c)))
    return ranked[:k]

exercise.starter:
def group_rearrangements(words):
    """Group words by their sorted-letters signature."""
    pass

exercise.solution:
def group_rearrangements(words):
    groups = {}
    for w in words:
        sig = ''.join(sorted(w))   # canonical form
        groups.setdefault(sig, []).append(w)
    return groups

exercise.starter:
def rack_after_jobs(tools, capacity):
    """Simulate the rack; return final contents front-to-back."""
    pass

exercise.solution:
def rack_after_jobs(tools, capacity):
    if capacity <= 0:
        return []
    rack = []
    for t in tools:
        if t in rack:
            rack.remove(t)        # take it out of its old spot
        rack.append(t)           # most recently used at the back
        while len(rack) > capacity:
            rack.pop(0)           # stalest tool leaves from the front
    return rack

exercise.starter:
def pair_scan(cars, target):
    """Return (i, j) of the earliest-completing pair, or None."""
    pass

exercise.solution:
def pair_scan(cars, target):
    first_at = {}                  # tonnage -> earliest index
    for j, x in enumerate(cars):
        need = target - x
        if need in first_at:
            return (first_at[need], j)
        if x not in first_at:       # keep only the FIRST sighting
            first_at[x] = j
    return None
